from __future__ import annotations

from artifact_tool_v2.rpc.client import JsonRpcClient
from artifact_tool_v2.rpc.types import ArtifactOperations

try:
    import caas_jupyter_tools
except Exception:
    caas_jupyter_tools = None


if caas_jupyter_tools is not None and not hasattr(JsonRpcClient, "_handle_operations_original"):
    JsonRpcClient._handle_operations_original = JsonRpcClient._handle_operations  # type: ignore[attr-defined]

    def _handle_operations_with_callback(
        self: JsonRpcClient, operations: ArtifactOperations
    ) -> None:
        self._handle_operations_original(operations)  # type: ignore[attr-defined]
        has_operations = len(operations.operations) > 0
        has_crdt_update = operations.crdtUpdateV2 is not None
        if not has_operations and not has_crdt_update:
            return
        if caas_jupyter_tools is None:
            return
        try:
            caas_jupyter_tools.record_artifact_tool_operations(operations.model_dump())
        except Exception:
            # Best-effort; don't fail RPC calls if callback fails.
            return

    JsonRpcClient._handle_operations = _handle_operations_with_callback  # type: ignore[assignment]
